export function makeStars(container,reduced){if(!container||reduced)return()=>{};const fragment=document.createDocumentFragment();for(let i=0;i<75;i++){const s=document.createElement("i");s.className="rm-star";s.style.setProperty("--x",`${(i*37.7)%100}%`);s.style.setProperty("--y",`${(i*61.3)%100}%`);s.style.setProperty("--size",`${2+i%3}px`);s.style.setProperty("--duration",`${2+i%5}s`);s.style.setProperty("--delay",`${-(i%7)}s`);fragment.append(s);}container.append(fragment);return()=>container.replaceChildren();}
export function observeReveals(root,reduced){const els=[...root.querySelectorAll(".reveal")];if(reduced||!window.IntersectionObserver){els.forEach(e=>e.classList.add("visible"));return()=>{};}const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");observer.unobserve(e.target);}}),{threshold:.08});els.forEach(e=>observer.observe(e));return()=>observer.disconnect();}
